) AS (
  VALUES 
    (515::BIGINT, 'Yo no sé quién inventó que este profesor es bueno. Califica durísimo. En las clases explica extremadamente rápido y asume que los estudiantes entienden. No tiene NADA de empatía. Se le queda la mayoría del curso pero el jura que el problema no es él, sino los estudiantes. NO LO RECOMIENDO.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2026-10-27T00:00:00+00:00'::TIMESTAMPTZ, '37a22824c0c78140059bc5d16d37482f286bddc6ebe25baa935bb870f70958ba'::TEXT, ARRAY[634]::BIGINT[]),
    (515::BIGINT, 'Best profe de mate'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-10-15T00:00:00+00:00'::TIMESTAMPTZ, '4fea1910543321c0b22687b0a022cc210ff9e03cb71a30a757a09386ad0d8e81'::TEXT, ARRAY[634]::BIGINT[]),
    (515::BIGINT, 'Mate Discreta es un curso muy difícil, pero Jeffry es buen profesor. Clases muy cargadas de explicaciones, el estudiante debe practicar por su cuenta luego, los apuntes de clase se suben, la evaluación se basa solo en quices y exámenes (poco favorecedor), el profe ayuda mucho'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '90d0a601f6d358808a4f4bcdccc4779cefab5115be628f65bf7cbbda9fa56e99'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-06T00:00:00+00:00'::TIMESTAMPTZ, '0eb6d6d7e1c25f1e13ec39b9c843d926acfd4b2c3a7a849e41b775f22a89caed'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'f8020504f3270b40bab6487ab314fd3fd99330dbdc65bd31f494b5222c719df4'::TEXT, ARRAY[634]::BIGINT[]),
    (515::BIGINT, 'En general el profe es una teja, explica muy bien y no da rodeos. Recomiendo 100% llevar álgebra con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '9d7d4318639d8888ce34bc012ae977e009cec596d1fa388b07b1cc57e2f57cfb'::TEXT, ARRAY[634]::BIGINT[]),
    (515::BIGINT, 'Excelente profesor. La segunda mate que llevo con él y sigo pensando que es el mejor profe. Revisa con mucho detalle los exámenes para darle puntos al estudiante y explica increíble.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '21e3ded0422e952b6a68021e8fc06cd4649fe8bf70fd15445509bbe49f66549f'::TEXT, ARRAY[634]::BIGINT[]),
    (515::BIGINT, 'Una teja de profe, debería tener mínimo 9,5 de calificación en esta plataforma. Matricule sin miedo. Calidad de persona, buenas clases, buen ambiente. Califica SUAVE le busca puntos de todo lado, súper empático. Lo amé'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-10-11T00:00:00+00:00'::TIMESTAMPTZ, '8242f31d90d09a4664ace0a828c938f8ee27e77b329d2eef7fb41375b3bebf70'::TEXT, ARRAY[634]::BIGINT[]),
    (515::BIGINT, 'Explica muy bien, usa ejemplos puntuales, ayuda mucho al estudiante, sin duda volvería a llevar verano con este profe, 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'd5ac45a3396aca3bc89a663a3d0b7b268575cae7c0cf82ee4bfb4f64db75f124'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'El profe es demasido amable y comprensivo sabe que el curso es dificil entonces es paciente con las dudas. Se nota que le gusta enseñar y que tiene interes en que aprendamos'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2024-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'd3f9376f2acbfeaf00599be8faed8474cab20678c4108738362d9d13c8dc38b9'::TEXT, ARRAY[103]::BIGINT[]),
    (515::BIGINT, 'Uno de los mejores profes, si puede matricular con él hagalo sin dudar, deja la materia muy clara y siempre está dispuesto a ayudar a los estudiantes, es muy comprensible y además da muy buena retroalimentación y material de apoyo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '382614d71dbbc7767dbf31399795677e937eb8a262db5c2974cd3af18f3aa776'::TEXT, ARRAY[605]::BIGINT[]),
    (515::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9b83b82171cb363373777fe73c0b65969f9dc9a541d00a2915cdb77428001503'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Es muy buen profesor y los inspira a uno, es un curso que hay que tenerle cuidado pero los ejemplo que él da en clase y las prácticas/quices que hace son muy acertadas a los exámenes, entonces los pueden utilizar para estudiar, intenten sacar las notas altas en los primeros 2 exámenes'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'b92c20934ddf56d9ccadd5b645b0d57024cd61527b45a76258f7f00e280b1df5'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Es super buen profe, siempre intenta dejar todos los temas claros y esta dispuesto siempre para ayudar al estudiante, el curso es dificil pero deja la materia super clara.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '7a450c95c3705b57a2cf9391f8db7a05a7bef49937edb13bb01823b8a6b84609'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Es un excelente profesor en todo el sentido de la palabra. Siempre brinda apoyo al estudiante, sus clases son largar, pero bastante claras. El se preocupa de que los estudiantes entiendan la materia. A este curso le tienen que dedicar mucho tiempo, tienen que llegar estudiados a la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'bbe6fa2d1efe66a2bc769121a2c84dae41f5d69d7e9090ab62463a4b00b189f1'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Al curso en sí hay que dedicarle demasiado tiempo si quiere pasar, es un curso bastante pesado. Con respecto al profesor, le gusta que llevemos las consignas al día, al principio cuesta agarrarle el toque, pero se logra. Procure sacar buena nota en los primeros dos exámenes, el tercero es mortal :)'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e6b4b50cca3ba4be3f6a3bbc21e27aa908597b6cf50fe4c74255509d2304d732'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Muy buen profesor, se le entiende bastante bien y las clases se pasan rápido'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '888142d69508a93feb4e248114b6f85b08a8270080ab322e7811700c304dfbf5'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Es muy buen profesor y siempre estpa disponible para ayudar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'be9ec59a03a15f2a4fe45aa72ee7bb3b03b039f7c2dbc960991e91f98b554ffa'::TEXT, ARRAY[634]::BIGINT[]),
    (515::BIGINT, 'El profe es muuuuuy bueno, la verdad él siempre está ahí para ayudarlo y es súper servicial. Es un excelente profesor, totalmente recomendado. Eso sí, tiene que ponerle al curso, aunque es poco probable que se quede :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'd29ecbd478ff054d6c7995e2ed3fad7cb4f7d795af377a33d0571507ca9a5f94'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'sus clases son buenas, explica bien, volvería a tomar las clases.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b5d8a4011dc0cc808784d0e84048e8ce024a169e5453c6821df98b9d861ae4d8'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Al inicio del curso cree que todos tienen conocimiento previo, desde la virtualidad habla demasiado rápido pero si explica bien. Al curso hay que dedicarle mucho tiempo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '0e3e8ca4d9704cb33960b72a75159d5f6b37b3a58a6ee207a9ab50f860978066'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Excelente Profesor, como venía dando el curso semi-virtual antes de la pandemia se adaptó super bien a la virtualidad, es muy accesible y siempre está atento por si uno tiene alguna consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'bf482d5a6aef5aa2e9b5f66ff1b5ebff213b599ca55286376108ca4e4f1f6ba8'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Excelente profe, sabe mucho y aprendes mucho. Todas sus clases fueron estupendas. Excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '44b46b3ff84928457168b2f3bedaf2c717b0b93e304f9bfeef9cb90f3e6b03e5'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-05-28T00:00:00+00:00'::TIMESTAMPTZ, '2129655465552b7742ae3ebe5d7b9bba277f037b47df6e5428a315bb28ba540e'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ff1a12a2b57f74d52c2b77ff2bf927fd0c72926f93cd932741fc50d6e6fb681f'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Al fin entiendo bien mate discreta!!! La facilidad no es culpa de él , es del curso en sí, pero super buen profe'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-29T00:00:00+00:00'::TIMESTAMPTZ, '0866df8a7e127bc7223d6571598be295bb216f3f246569e45d9a2fc58eb7bf57'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Muy buen profe, me encantó la idea de tomar fotos de las pizarras que hacía y publicarlas en el grupo de facebook ya que me ayudó mucho!! Sus clases las disfruté bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f1467fa86d9abddae2b281d655cfe8bfd714f877b15461086932f6c8eed441ec'::TEXT, ARRAY[564]::BIGINT[]),
    (515::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3da4e654f6abebbb4d1bea675b94b35169bf3c2c8abfcfa0dab747091ed51664'::TEXT, ARRAY[1018]::BIGINT[]),
    (515::BIGINT, 'Excelente profesor, muy buenas prácticas para que el estudiante aprenda'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ced9e807e738438524fcecae908c6daf66648f55e473aaeea6726a81a6d756f7'::TEXT, ARRAY[1018]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
